versions.safe:
router.get("/orders/:id", async (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0) return res.status(400).send("Invalid order id");
  const [rows] = await db.query("SELECT id, total FROM orders WHERE id = ?", [id]);
  res.json(rows);
});

